<template><view class="wrap"><text class="h">Rubik 3×3 Guide</text><view class="muted">Học công thức • Luyện tập 3D • Offline</view><button class="btn" @click="openViewer">🎲 Mở Rubik 3D tự do</button><input class="search" v-model="keyword" placeholder="Tìm công thức, tầng, trường hợp" placeholder-style="color:#8292aa"/><view v-for="stage in stages" :key="stage"><view class="section">{{stage}}</view><view class="card" v-for="a in filtered.filter(x=>x.stage===stage)" :key="a.id" @click="openLesson(a.id)"><text class="tag">{{a.case}}</text><view class="itemtitle">{{a.title}}</view><view class="formula">{{a.original}}</view><view class="muted">Nhấn để xem chú thích và mô phỏng →</view></view></view><view class="muted" v-if="!filtered.length">Không tìm thấy công thức.</view></view></template>
<script setup>import {computed,ref} from 'vue';import algorithms from '../../static/data/algorithms.json';const keyword=ref('');const stages=['Tầng 1','Tầng 2','Tầng 3'];const filtered=computed(()=>algorithms.filter(a=>(a.title+' '+a.case+' '+a.original+' '+a.stage).toLowerCase().includes(keyword.value.toLowerCase())));const openLesson=id=>uni.navigateTo({url:'/pages/lesson/lesson?id='+id});const openViewer=()=>uni.navigateTo({url:'/pages/viewer/viewer'});</script>
<style scoped>.wrap{padding:32rpx}.search{margin-top:25rpx;padding:22rpx;background:#263348;border-radius:14rpx}.section{margin-top:30rpx;font-size:34rpx;font-weight:bold;color:#93c5fd}.itemtitle{font-weight:bold;font-size:30rpx;margin-top:8rpx}.muted{font-size:25rpx;margin-top:12rpx}</style>
